module ptw_summ (input wire [49:0] sv, input wire fin, output wire [9:0] sm);
    wire p0 = (^{sv[0], sv[1], sv[2], sv[3], sv[4], sv[5], sv[6], sv[7], sv[8]}) ^ (fin & (^{sv[9], sv[10], sv[11], sv[12], sv[13], sv[14], sv[15], sv[16], sv[17], sv[18], sv[19], sv[20]}));
    wire p1 = (^{sv[21], sv[22], sv[23], sv[24], sv[25], sv[26], sv[27], sv[28], sv[29]}) ^ (fin & (^{sv[30], sv[31], sv[32], sv[33], sv[34], sv[35], sv[36], sv[37], sv[38], sv[39], sv[40], sv[41]}));
    assign sm = {p1, p0, sv[49], sv[48], sv[47], sv[46], sv[45], sv[44], sv[43], sv[42]};
endmodule

